'use strict';

// MODULES //

var isInteger = require( '@stdlib/assert-is-integer' ).isPrimitive;
var unary = require( '@stdlib/ndarray-base-unary' );
var baseEmpty = require( '@stdlib/ndarray-base-empty' );
var getDType = require( '@stdlib/ndarray-base-dtype' );
var getShape = require( '@stdlib/ndarray-base-shape' );
var getOrder = require( '@stdlib/ndarray-base-order' );


// FUNCTIONS //

/**
* Normalizes a relative index.
*
* @private
* @param {integer} idx - relative index
* @param {NonNegativeInteger} len - number of indexed elements
* @returns {NonNegativeInteger} normalized index
*/
function normalize( idx, len ) {
	if ( idx < 0 ) {
		idx += len;
		if ( idx < 0 ) {
			return 0;
		}
		return idx;
	}
	if ( idx > len ) {
		return len;
	}
	return idx;
}


// MAIN //

/**
* Normalizes an index argument.
*
* ## Notes
*
* -   When a `target`, `start`, and/or `end` index is negative, the respective index is determined relative to the last indexed element, with out-of-bounds indices clamped to index bounds.
* -   If provided an ndarray, the function normalizes each element and returns a new ndarray having the same shape and data type as the provided ndarray.
*
* @private
* @param {(ndarray|integer)} idx - index argument
* @param {NonNegativeInteger} len - number of indexed elements
* @returns {(ndarray|NonNegativeInteger)} normalized index argument
*/
function normalizeIndices( idx, len ) {
	var out;

	if ( isInteger( idx ) ) {
		return normalize( idx, len );
	}
	out = baseEmpty( getDType( idx ), getShape( idx, false ), getOrder( idx ) );
	unary( [ idx, out ], clbk );
	return out;

	/**
	* Normalizes a relative index.
	*
	* @private
	* @param {integer} v - relative index
	* @returns {NonNegativeInteger} normalized index
	*/
	function clbk( v ) {
		return normalize( v, len );
	}
}


// EXPORTS //

module.exports = normalizeIndices;
